
#include "UbuntuFonts.h"
#include "fonts.h"

unsigned int Ubuntu40_raw_len = 484704;
unsigned char Ubuntu40_raw[];


void DD_LCD_DrawPixel(uint16_t x, uint16_t y, uint16_t color)
{
    uint16_t *fb = (uint16_t *)LCD_FRAMEBUFFER;
    fb[y * LCD_WIDTH + x] = color;
}


void DD_LCD_DrawChar40(uint16_t x, uint16_t y, char c, uint16_t color)
{
    uint32_t index = (c - 32) * 48;   // 16x24 font = 48 bytes per char

    for(int row = 0; row < 24; row++)
    {
        for(int col = 0; col < 16; col++)
        {
            uint8_t byte = Ubuntu40_raw[index + (row * 2) + (col / 8)];
            uint8_t bit  = 7 - (col % 8);

            if(byte & (1 << bit))
            {
                DD_LCD_DrawPixel(x + col, y + row, color);
            }
        }
    }
}

